export type Scenario = {
  id: string; title: string; description: string; expectedRootCause: string; learningObjectives: string[];
  evidence: {action: string; output: string; interpretation: string}[]; mitigation: string; prevention: string;
  runbook: {containment: string; commands: {label: string; command: string; why: string}[]; escalation: string};
  category: string;
};

const kubectlPodCommands = [
  {label: 'Object and events', command: 'kubectl describe pod <pod> -n <namespace>', why: 'Read the scheduler, lifecycle, probe, and termination evidence before changing the workload.'},
  {label: 'Previous container output', command: 'kubectl logs <pod> -n <namespace> -c <container> --previous', why: 'A restarted container may have lost its only useful application-level error.'},
  {label: 'Scoped live state', command: 'kubectl get pod <pod> -n <namespace> -o yaml', why: 'Compare intended spec, status, resource limits, node placement, and recent conditions.'},
];
const gpuCommands = [
  {label: 'GPU inventory', command: 'kubectl describe node <node> | sed -n \'/Allocatable:/,/System Info:/p\'', why: 'Confirm the resource the scheduler actually sees; do not infer it from a dashboard.'},
  {label: 'Driver and hardware evidence', command: 'sudo dmesg -T | grep -Ei \'NVRM|Xid\' && nvidia-smi -q', why: 'Correlate host driver/hardware events with the affected GPU UUID.'},
  {label: 'Operator operands', command: 'kubectl get pods -n gpu-operator -o wide && kubectl logs -n gpu-operator -l app=nvidia-device-plugin --tail=200', why: 'Separate a device-plugin/driver failure from a workload scheduling issue.'},
];
const fabricCommands = [
  {label: 'NCCL signal', command: 'NCCL_DEBUG=INFO NCCL_DEBUG_SUBSYS=NET,INIT <launch-command>', why: 'Capture interface and peer-selection evidence before changing NCCL knobs.'},
  {label: 'Link and topology', command: 'ibstatus; ibstat; nvidia-smi topo -m', why: 'Verify active ports, expected rate/layer, and GPU-to-NIC locality.'},
  {label: 'RoCE counters', command: 'ethtool -S <nic> | grep -Ei \'drop|err|pause|pfc|ecn\'', why: 'Rising drops, pause, PFC, or ECN signals point to fabric configuration or congestion, not an application bug.'},
];
const nodeCommands = [
  {label: 'Node conditions', command: 'kubectl describe node <node>', why: 'Check Ready, MemoryPressure, DiskPressure, PIDPressure, taints, and recent events.'},
  {label: 'Runtime filesystem', command: 'sudo df -h /var/lib/containerd; sudo df -i /var/lib/containerd', why: 'Check both bytes and inodes before reclaiming images or restarting kubelet.'},
  {label: 'Kubelet evidence', command: 'sudo journalctl -u kubelet --since \'30 min ago\' --no-pager', why: 'Find the mechanism behind a NotReady transition, rather than treating it as a generic node failure.'},
];
const linuxCommands = [
  {label: 'Pressure overview', command: 'uptime; vmstat 1 5; cat /proc/pressure/{cpu,memory,io}', why: 'Separate runnable CPU pressure, blocked I/O, reclaim, and sustained stall time.'},
  {label: 'Process evidence', command: 'ps -eo pid,ppid,stat,wchan:32,pcpu,pmem,comm --sort=-pcpu | head -30', why: 'Find runnable, D-state, zombie, memory-heavy, or blocked processes and the kernel wait point.'},
  {label: 'Per-process behavior', command: 'sudo pidstat -durw 1 5; sudo lsof -p <pid> | head', why: 'Correlate CPU, I/O, faults, context switches, and open resources with the affected service.'},
];
const controlPlaneCommands = [
  {label: 'API readiness', command: 'kubectl get --raw=/readyz?verbose', why: 'Identify the unhealthy API-server dependency without relying on a generic health dashboard.'},
  {label: 'Request pressure', command: 'kubectl get --raw=/metrics | grep -E \'apiserver_request_duration|apiserver_current_inflight\'', why: 'Check latency and concurrency by verb/resource before blaming etcd.'},
  {label: 'etcd signal', command: 'etcdctl endpoint status --cluster -w table; etcdctl endpoint health --cluster', why: 'Inspect leader, revision, database size, raft index, and endpoint health with quorum awareness.'},
];
const automationCommands = [
  {label: 'Execution record', command: 'python -m your_tool --dry-run --log-format=json', why: 'Preserve inputs, planned actions, correlation ID, and dry-run output before allowing mutation.'},
  {label: 'Retry and deadline metrics', command: 'sum by (operation,status) (rate(automation_attempts_total[5m]))', why: 'Distinguish useful retry from amplification and permanent-error loops.'},
  {label: 'Idempotency audit', command: 'pytest -q tests/test_idempotency.py tests/test_partial_failure.py', why: 'Reproduce repeated execution and mid-flight failure before rerunning against production.'},
];
const observabilityCommands = [
  {label: 'Target health', command: 'up{job=~".*gpu.*|.*dcgm.*"}', why: 'Separate missing telemetry from a healthy zero-valued metric.'},
  {label: 'Cardinality', command: 'topk(20, count by (__name__)({__name__=~".+"}))', why: 'Find unexpectedly expensive metric families before changing Prometheus resources.'},
  {label: 'Pipeline evidence', command: 'kubectl logs -n monitoring <collector-or-exporter-pod> --since=30m', why: 'Trace scrape/export/remote-write failures through the telemetry path.'},
];
const slurmCommands = [
  {label: 'Queue reason', command: 'squeue -j <jobid> -o "%.18i %.9P %.8j %.8T %.10M %.6D %R"', why: 'The pending reason is the first scheduling branch, not an error to bypass.'},
  {label: 'Job request', command: 'scontrol show job <jobid>', why: 'Inspect requested GRES/TRES, constraints, partition, reservation, priority, and dependency.'},
  {label: 'Capacity and state', command: 'sinfo -Nel; scontrol show node <node>', why: 'Compare request with allocatable GPU type/topology and drained/down node reasons.'},
];
const bmcCommands = [
  {label: 'BMC reachability', command: 'ping -c3 <bmc-ip>; ipmitool -I lanplus -H <bmc-ip> -U admin -P *** chassis status', why: 'Confirm whether the BMC network path itself is down before assuming the firmware update is merely slow.'},
  {label: 'Redfish task/update state', command: 'curl -sk -u admin:*** https://<bmc-ip>/redfish/v1/TaskService/Tasks | jq .', why: 'A stuck update usually still has a Task resource reporting percent-complete or an error state even when new Redfish requests stop responding.'},
  {label: 'Out-of-band console', command: 'ipmitool -I lanplus -H <bmc-ip> -U admin -P *** sol activate', why: 'Serial-over-LAN can reveal a POST hang or a wedged BMC even when the Redfish HTTPS listener itself is unresponsive.'},
];
const pxeCommands = [
  {label: 'DHCP/TFTP capture', command: 'tcpdump -i eth0 port 67 or port 68 or port 69', why: 'Pinpoint the exact stage: no DHCPDISCOVER, offer but no TFTP fetch, or fetch but boot-mode mismatch.'},
  {label: 'DHCP scope and MAC registration', command: 'grep -i <mac> /etc/dhcp/dhcpd.conf; grep <mac> provisioning-system-inventory.csv', why: 'A mainboard RMA changes the MAC address; most provisioning systems require MAC pre-registration before offering PXE options.'},
  {label: 'Boot-mode and bootfile match', command: 'diff pxelinux.cfg/<old-mac> grub.cfg; ipmitool chassis bootparam get 5', why: 'Confirm the DHCP-handed bootfile-name matches the NIC firmware mode (legacy BIOS vs UEFI/HTTPBoot), which BIOS defaults can silently flip after an RMA.'},
];
const bcmCommands = [
  {label: 'Category-rendered state', command: 'cmsh -c "category use gpu-a100; show"', why: 'Confirm what the category says every member node should be running before comparing it to what one node actually has.'},
  {label: 'Node-level override diff', command: 'cmsh -c "device use gpu-node-09; show"; diff category-rendered-config node-actual-config', why: 'A hand-edit made outside the category shows up as a per-node override the category push cannot see or correct.'},
  {label: 'Provision/health history', command: 'cmsh -c "device use gpu-node-09; grabimage -w"', why: 'Determine whether the node has been reprovisioned since the manual edit, which decides if the drift is transient or has become permanent.'},
];
const ansibleCommands = [
  {label: 'Check/diff against target', command: 'ansible-playbook site.yml --limit gpu_nodes --check --diff', why: 'See the exact byte-level diff driving the changed= count before trusting or dismissing it.'},
  {label: 'Idempotency re-verification', command: 'ansible-playbook site.yml --limit <node> --check --diff   # run 3x consecutively', why: 'True idempotency is zero diff on a third consecutive run against an untouched node, not merely a successful exit code.'},
  {label: 'Source-data ordering audit', command: 'ansible <node> -m debug -a "var=dcgm_metrics_dict"', why: 'Confirm whether the underlying dict/merge order, not the rendered values, is what is unstable across runs.'},
];
const terraformCommands = [
  {label: 'Plan with replace markers isolated', command: 'terraform plan -out=tfplan; terraform show -json tfplan | jq \'.resource_changes[] | select(.change.actions|length>1)\'', why: 'Isolate every -/+ destroy-and-recreate action before scrolling past the plan summary line.'},
  {label: 'State vs real-infra refresh', command: 'terraform state show <resource>; terraform plan -refresh-only', why: 'Determine whether the divergence is state believing something reality no longer matches, rather than a real declared-config change.'},
  {label: 'Manual-change correlation', command: 'git log -p -- <resource>.tf; cloud console/audit-log history for <resource-id>', why: 'Correlate an out-of-band manual change with the moment state stopped matching reality.'},
];
const mpiCommands = [
  {label: 'Rank launch confirmation', command: 'srun --overlap --jobid=<id> ps aux | grep python', why: 'Confirm every expected rank process actually started before suspecting the NCCL/fabric layer at all.'},
  {label: 'MPI/PMIx bootstrap evidence', command: 'mpirun --report-bindings -np 8 ...; export PMIX_MCA_ptl_base_verbose=5', why: 'Missing or incomplete bindings output for one node means PMIx never heard back from it — an MPI/launch problem, not NCCL.'},
  {label: 'NCCL handoff point', command: 'NCCL_DEBUG=INFO NCCL_DEBUG_SUBSYS=INIT,NET <launch-command>', why: 'If MPI bootstrap completed for every rank and the hang begins at init_process_group, the problem has moved into NCCL/fabric territory.'},
];
const enrootCommands = [
  {label: 'Host-level GPU baseline', command: 'nvidia-smi -L', why: 'Confirm the driver/host GPU path is healthy before suspecting the container runtime at all.'},
  {label: 'Enroot NVIDIA hook presence', command: 'ls -l /etc/enroot/hooks.d/*nvidia*', why: 'Enroot only bind-mounts driver libraries/devices into the rootless filesystem if this hook file is present and enabled.'},
  {label: 'Container-side visibility env', command: 'srun --container-image=... --container-remap-root env | grep NVIDIA_VISIBLE_DEVICES', why: 'An empty or unset NVIDIA_VISIBLE_DEVICES inside the container is the tell that the hook never fired.'},
];
const selinuxCommands = [
  {label: 'Denial record', command: 'ausearch -m avc -ts recent', why: 'Find the exact denied syscall/path before assuming the monitoring agent itself is broken.'},
  {label: 'Human-readable explanation', command: 'audit2why < denial.log', why: 'Translate the raw AVC denial into which type/context mismatch is actually blocking access.'},
  {label: 'Mode and policy scope', command: 'sestatus; semanage fcontext -l | grep nvidia', why: 'Confirm enforcing mode and whether a GPU/monitoring-specific policy module or context mapping is missing entirely from the targeted policy.'},
];
const changeMgmtCommands = [
  {label: 'Compatibility matrix audit', command: 'diff canary_inventory.csv fleet_inventory.csv   # NIC model, firmware rev, GPU SKU', why: 'A canary that passes validates only the hardware/firmware variants it actually contains, nothing else in the fleet.'},
  {label: 'Canary validation gate results', command: 'dcgm-diag -r 3; nccl-tests all_reduce_perf   # canary set only', why: 'Bandwidth within baseline on the canary says nothing about a variant the canary never included.'},
  {label: 'Fleet stratification check', command: 'awk -F, \'{print $3}\' fleet_inventory.csv | sort | uniq -c', why: 'Quantify what fraction of the fleet the canary failed to represent before authorizing the next wave.'},
];
const dkmsCommands = [
  {label: 'Driver load failure signature', command: 'dmesg | grep -i nvidia; nvidia-smi', why: 'Confirm the failure is a DKMS/NVML driver-library version mismatch, not a hardware fault.'},
  {label: 'DKMS build status', command: 'dkms status', why: 'Determine whether the nvidia module built for the new kernel at all, or is still registered only against the previous kernel.'},
  {label: 'Patch pipeline sequencing', command: 'grep -i kernel /var/log/patch-pipeline.log', why: 'Confirm whether the kernel package update and DKMS rebuild were ever gated as one atomic step before the reboot.'},
];
const cicdCommands = [
  {label: 'Policy-check gate result', command: 'conftest test tfplan.json -p policy/', why: 'Confirm whether the destructive plan was actually blocked by policy, or whether it was bypassed.'},
  {label: 'Override-path audit trail', command: 'grep -i override pipeline_audit.log; git log --grep=\'emergency-override\'', why: 'An override that bypassed policy check should still leave an audit trail; its absence is itself the finding.'},
  {label: 'Post-hoc plan reconciliation', command: 'terraform plan -refresh-only', why: 'Determine what was actually applied versus what the bypassed policy check would have flagged, now that it is too late to block it.'},
];

function runbookFor(id: string): Scenario['runbook'] {
  if (['gpu-unavailable', 'driver-mismatch', 'mig', 'xid', 'low-gpu', 'topology'].includes(id)) return {containment: 'Avoid rescheduling blindly onto the same suspect node. Cordon it for a node-local driver or hardware signal; drain only when workload disruption is approved and a checkpoint/redundancy plan exists.', commands: gpuCommands, escalation: 'Escalate with node name, GPU UUID/PCI bus ID, driver and CUDA versions, Xid/NVRM excerpt, device-plugin logs, and the exact workload image digest.'};
  if (['nccl', 'roce', 'rdma-perf', 'scaling'].includes(id)) return {containment: 'Stop expanding the affected distributed job and preserve logs. Do not change global fabric PFC/ECN, routing, or NCCL defaults without network-owner approval and a rollback plan.', commands: fabricCommands, escalation: 'Escalate with affected node pairs/rack or rail, NCCL log timestamps, interface/IP mapping, link state/rate, counter deltas, and a known-good baseline.'};
  if (['notready'].includes(id)) return {containment: 'Cordon the node first to prevent new placement. Preserve disk and journal evidence before deleting images, restarting containerd, or rebooting.', commands: nodeCommands, escalation: 'Escalate with node conditions, filesystem byte/inode use, kubelet/container-runtime logs, image-GC state, and scope of affected workloads.'};
  if (['high-load', 'memory-reclaim', 'fd-exhaustion', 'tls-expiry'].includes(id)) return {containment: 'Protect the affected service from additional load and preserve host evidence. Avoid rebooting or killing processes until ownership, redundancy, and recoverability are understood.', commands: linuxCommands, escalation: 'Escalate with host/service identity, start of impact, process state, PSI/vmstat/pidstat evidence, relevant journal entries, limits, dependency state, and the last change.'};
  if (['api-etcd', 'gitops-drift'].includes(id)) return {containment: 'Freeze nonessential control-plane mutations and automated reconciliation only when the blast radius justifies it. Preserve audit logs and revision/change context.', commands: controlPlaneCommands, escalation: 'Escalate with API readiness, latency by verb/resource, inflight requests, etcd endpoint/quorum state, audit evidence, Git revision, and safe rollback decision.'};
  if (['retry-storm', 'partial-automation'].includes(id)) return {containment: 'Pause the specific automation actor or reduce its concurrency; do not disable unrelated controllers. Record correlation IDs and partial mutations before retrying.', commands: automationCommands, escalation: 'Escalate with tool version, invocation inputs, dry-run/diff, structured logs, attempts and deadline metrics, partial-success inventory, idempotency evidence, and rollback plan.'};
  if (['missing-gpu-metrics', 'cardinality'].includes(id)) return {containment: 'Treat missing telemetry as unknown—not healthy. Protect alerting and query capacity while preserving the scrape/export pipeline evidence.', commands: observabilityCommands, escalation: 'Escalate with affected metric/target, scrape and exporter logs, label/cardinality deltas, query timing, retention/remote-write state, and the last dashboard or instrumentation change.'};
  if (['slurm-pending', 'slurm-fairshare-starve', 'slurm-failover-lost-jobs'].includes(id)) return {containment: 'Do not cancel and resubmit repeatedly or drain nodes to force placement. Preserve the exact job request, pending reason, and controller/accounting state.', commands: slurmCommands, escalation: 'Escalate with job ID, partition/QOS/account, GRES/TRES and constraints, pending reason/priority, eligible node state, reservation/dependency, and capacity owner.'};
  if (id === 'bmc-unreachable-fw-update') return {containment: 'Do not power-cycle blindly while an update is in flight — a forced power event mid-flash can brick the BMC. Attempt out-of-band console access before any power action.', commands: bmcCommands, escalation: 'Escalate with BMC firmware version before/after, Redfish Task resource state, vendor support case if the BMC is unresponsive to all paths, and physical-access owner for the rack.'};
  if (id === 'pxe-boot-after-rma') return {containment: 'Do not swap in a different NIC or reflash BIOS speculatively before the DHCP/TFTP capture confirms which stage is failing. Work the D-T-B-I decomposition in order.', commands: pxeCommands, escalation: 'Escalate with node serial/MAC before and after RMA, DHCP/TFTP capture excerpt, provisioning-system registration status, and boot-mode (BIOS/UEFI) setting.'};
  if (id === 'bcm-category-drift') return {containment: 'Do not force a category re-push blindly onto a hand-edited node — reconcile the diff first so the push does not silently clobber an intentional emergency fix.', commands: bcmCommands, escalation: 'Escalate with category name, image version, the exact node-level diff, who made the manual edit and why, and whether other nodes in the category are similarly affected.'};
  if (id === 'ansible-false-idempotent') return {containment: 'Stop treating changed= as noise. Freeze further re-runs against the affected role until the ordering source is identified, so a real unauthorized change is not lost inside a known-false-positive signal.', commands: ansibleCommands, escalation: 'Escalate with the templated task name, three consecutive --check --diff outputs, the source dict/merge structure, and the affected node list.'};
  if (id === 'terraform-state-drift-destroy') return {containment: 'Do not apply a plan showing an unexpected -/+ on a resource nobody intended to touch. Treat that marker as an automatic stop for manual review, regardless of how routine the rest of the plan looks.', commands: terraformCommands, escalation: 'Escalate with the resource address, the manual change that caused drift, the exact attribute forcing replacement, and whether the resource holds unrecoverable data.'};
  if (id === 'mpi-nccl-startup-hang') return {containment: 'Do not restart the job repeatedly without first determining which side of the MPI/NCCL handoff point it stalled at — a blind retry burns allocation time without new information.', commands: mpiCommands, escalation: 'Escalate with job ID, per-rank bootstrap/bindings output, the last NCCL_DEBUG line per rank, and node/rail pairing for the stalled rank.'};
  if (id === 'enroot-gpu-not-visible') return {containment: 'Confirm the host GPU path is healthy before touching Enroot config, so a driver fix is not mistakenly attempted for a container-runtime problem.', commands: enrootCommands, escalation: 'Escalate with node name, hook file presence/version, NVIDIA_VISIBLE_DEVICES value inside the container, and whether Kubernetes GPU workloads on the same node are unaffected.'};
  if (['selinux-gpu-monitoring-block', 'os-hardening-breaks-rdma'].includes(id)) return {containment: 'Do not disable enforcement or the profile fleet-wide to make the symptom disappear. Treat setenforce 0/complain mode as a temporary diagnostic step only, with a tracked follow-up.', commands: selinuxCommands, escalation: 'Escalate with the exact AVC denial or sysctl/firewall diff, the audit2why explanation, the hardening baseline version applied, and the compensating-control owner if a risk-acceptance decision is needed.'};
  if (id === 'canary-firmware-not-representative') return {containment: 'Halt further rollout waves immediately. Do not resume based on the canary\'s prior pass — that evidence no longer covers the hardware variant now failing.', commands: changeMgmtCommands, escalation: 'Escalate with the compatibility matrix, canary stratification criteria used, the specific firmware revision affected, and the percentage of fleet on that revision.'};
  if (id === 'cicd-emergency-override-bypass') return {containment: 'Freeze further use of the override path pending audit. Do not treat the applied change as validated just because it succeeded technically.', commands: cicdCommands, escalation: 'Escalate with the override justification on record (or its absence), the policy rule that was bypassed, the blast radius of what was actually applied, and the recovery/rollback plan.'};
  if (id === 'kernel-patch-dkms-break') return {containment: 'Do not reboot the remaining batches into the new kernel until the DKMS rebuild gate is confirmed working. Hold the patch wave at its current batch.', commands: dkmsCommands, escalation: 'Escalate with kernel version before/after, dkms status output, affected node count in the batch, and whether untouched batches can be safely held.'};
  return {containment: 'Start with a canary or the smallest affected scope. Prefer reversible configuration changes; do not delete Pods, PVCs, or data to make the symptom disappear.', commands: kubectlPodCommands, escalation: 'Escalate with impact and timeline, exact object events, manifests or relevant diff, logs/metrics for the failing window, changes already attempted, and a safe rollback point.'};
}

function categoryFor(id: string): string {
  if (['crashloop', 'pending', 'notready', 'oom', 'cpu-throttle', 'dns', 'network-policy', 'pvc', 'hpa', 'api-etcd', 'gitops-drift'].includes(id)) return 'Kubernetes';
  if (['gpu-unavailable', 'driver-mismatch', 'mig', 'xid', 'ttft', 'low-gpu'].includes(id)) return 'GPU/Driver';
  if (['nccl', 'roce', 'rdma-perf', 'scaling', 'topology'].includes(id)) return 'Networking/Fabric';
  if (['storage'].includes(id)) return 'Storage & Data';
  if (['high-load', 'memory-reclaim', 'fd-exhaustion'].includes(id)) return 'Linux/Systems';
  if (['retry-storm', 'partial-automation'].includes(id)) return 'Automation & Python';
  if (['missing-gpu-metrics', 'cardinality'].includes(id)) return 'Observability';
  if (['tls-expiry'].includes(id)) return 'Security';
  if (['bmc-unreachable-fw-update', 'pxe-boot-after-rma', 'bcm-category-drift'].includes(id)) return 'Bare-metal/BCM';
  if (['ansible-false-idempotent', 'terraform-state-drift-destroy'].includes(id)) return 'IaC (Ansible/Terraform)';
  if (['slurm-pending', 'slurm-fairshare-starve', 'slurm-failover-lost-jobs', 'mpi-nccl-startup-hang', 'enroot-gpu-not-visible'].includes(id)) return 'Slurm/HPC';
  if (['selinux-gpu-monitoring-block', 'kernel-patch-dkms-break', 'os-hardening-breaks-rdma'].includes(id)) return 'Security';
  if (['canary-firmware-not-representative', 'cicd-emergency-override-bypass'].includes(id)) return 'Change Management';
  return 'Kubernetes';
}

const make = (id: string, title: string, description: string, root: string, evidence: string[], mitigation: string, prevention: string): Scenario => ({
  id, title, description, expectedRootCause: root,
  learningObjectives: ['Form competing hypotheses', 'Choose high-information checks', 'Separate symptom, cause, mitigation, and prevention'],
  evidence: [
    {action: 'Establish scope and recent change', output: evidence[0], interpretation: 'Use blast radius and timing to rank hypotheses.'},
    {action: 'Inspect workload and control-plane evidence', output: evidence[1], interpretation: 'Object state narrows the failing lifecycle boundary.'},
    {action: 'Inspect node, runtime, and dependency evidence', output: evidence[2], interpretation: 'Correlate host evidence with the workload symptom.'},
    {action: 'Run the targeted validation', output: evidence[3], interpretation: 'Validate the leading hypothesis before mitigation.'},
  ], mitigation, prevention, runbook: runbookFor(id), category: categoryFor(id),
});

export const scenarios: Scenario[] = [
  make('crashloop', 'CrashLoopBackOff', 'A new API Pod repeatedly restarts after rollout.', 'A required config key was renamed; the process exits during startup.', ['Only the new ReplicaSet fails after a config rollout.', 'Last termination: exit 1; events show exponential restart backoff.', 'Container log: KeyError DATABASE_URL; Secret contains DB_URL.', 'A canary with the corrected key becomes Ready.'], 'Restore the compatible key and roll back or restart safely.', 'Schema-check configuration in CI and use startup probes deliberately.'),
  make('pending', 'Pending Pod', 'A GPU workload remains Pending although the cluster has idle CPU.', 'No node has the requested GPU resource and required topology label together.', ['Only GPU jobs with zone affinity are affected.', 'FailedScheduling: insufficient nvidia.com/gpu and affinity mismatch.', 'GPU nodes are Ready; the requested zone contains CPU-only nodes.', 'Removing affinity schedules; placing GPU capacity in-zone also succeeds.'], 'Correct the constraint or provide matching capacity.', 'Validate placement constraints against capacity inventory.'),
  make('notready', 'Node NotReady', 'One worker stops accepting Pods.', 'Disk pressure filled the runtime filesystem and kubelet stopped reporting.', ['A single node is affected after image churn.', 'Node condition Ready=Unknown; DiskPressure=True.', 'journalctl shows image GC failures; /var/lib/containerd is full.', 'Freeing safe reclaimable images restores kubelet heartbeats.'], 'Cordon, reclaim runtime disk safely, restart only if required, then uncordon after validation.', 'Reserve disk, alert on inode/space pressure, and tune image GC.'),
  make('oom', 'OOMKilled', 'An inference container is killed under burst load.', 'KV-cache growth exceeds the container memory limit.', ['Failures correlate with long-context traffic.', 'Last state OOMKilled; memory limit is 16Gi.', 'Working set climbs with active sequence tokens; node has free memory.', 'Capping tokens/concurrency keeps the cgroup below its limit.'], 'Reduce concurrency/context or raise the evidence-based limit.', 'Capacity-test KV cache and expose token-weighted saturation metrics.'),
  make('cpu-throttle', 'CPU throttling', 'Latency rises while CPU utilization looks moderate.', 'A low CPU limit causes CFS quota throttling during bursts.', ['Only latency-sensitive sidecars with limits regress.', 'Pod CPU is below one core on average.', 'cpu.stat shows rapidly rising nr_throttled and throttled_usec.', 'A canary with a justified limit/removal restores tail latency.'], 'Adjust the CPU limit after safety review.', 'Track throttling and size limits from burst demand, not averages.'),
  make('dns', 'DNS failure', 'Pods intermittently fail service-name lookups.', 'CoreDNS is saturated and dropping/queuing queries.', ['Cross-namespace DNS fails during deployment bursts.', 'Services and EndpointSlices are correct.', 'CoreDNS CPU throttles; request duration and SERVFAIL rise.', 'Scaling CoreDNS and removing its restrictive CPU limit clears failures.'], 'Restore DNS capacity and verify caching behavior.', 'Monitor DNS latency/errors and capacity-test query bursts.'),
  make('network-policy', 'NetworkPolicy denial', 'A newly deployed namespace cannot reach a shared API.', 'Default-deny was added without an egress allow rule.', ['Only the new namespace fails after policy rollout.', 'Service discovery succeeds; TCP connect times out.', 'CNI policy counters show denied egress to the API namespace.', 'A narrowly scoped egress rule restores the canary.'], 'Add least-privilege egress for the required destination/port.', 'Test policy intent in staging and maintain ownership metadata.'),
  make('pvc', 'PVC Pending', 'A StatefulSet cannot start because its claim is Pending.', 'The requested StorageClass uses delayed binding but no schedulable topology satisfies the Pod.', ['Claims using one zonal class are affected.', 'PVC: WaitForFirstConsumer; Pod: topology conflict.', 'No eligible node exists in the PV provisioner zone.', 'Adding eligible capacity or changing the valid topology binds the claim.'], 'Align node, workload, and storage topology.', 'Continuously reconcile zonal capacity with storage classes.'),
  make('hpa', 'HPA not scaling', 'Request rate climbs but replicas stay fixed.', 'The custom metric adapter returns no series because labels changed.', ['Only the custom-metric HPA is affected.', 'HPA condition ScalingActive=False; metric unknown.', 'Adapter query returns empty after application label rename.', 'Corrected selector returns values and desired replicas increases.'], 'Fix the metric selector and observe controlled scaling.', 'Contract-test metrics and alert on invalid HPA conditions.'),
  make('gpu-unavailable', 'GPU unavailable', 'A Pod requests a GPU but nodes advertise none.', 'The NVIDIA device plugin is crash-looping after driver initialization failure.', ['All Pods on one GPU pool are Pending.', 'Allocatable nvidia.com/gpu is absent.', 'Device-plugin log cannot load NVML; nvidia-smi fails on host.', 'Restoring the validated driver makes NVML and allocatable resources return.'], 'Cordon affected nodes and restore the known-good driver stack.', 'Use GPU Operator readiness and golden-node validation.'),
  make('driver-mismatch', 'GPU driver mismatch', 'CUDA workloads fail immediately after a node image update.', 'The container CUDA requirement is newer than the installed driver supports.', ['Only newer workload images fail on updated scheduling.', 'Container reports CUDA driver version insufficient.', 'nvidia-smi driver version is below the image compatibility floor.', 'Known-compatible image succeeds on the same node.'], 'Roll back the image or upgrade the driver through the validated lifecycle.', 'Enforce a driver/CUDA compatibility matrix in admission and release tests.'),
  make('mig', 'MIG resource issue', 'A Pod requesting a MIG profile never schedules.', 'Nodes are partitioned into a different MIG geometry than requested.', ['Only one MIG resource profile is unavailable.', 'FailedScheduling reports insufficient nvidia.com/mig-2g.20gb.', 'nvidia-smi mig -lgi shows only 1g and 3g instances.', 'Reconfiguring a drained test node to the required geometry advertises the resource.'], 'Drain and reconcile the approved MIG geometry.', 'Treat MIG layouts as capacity products with demand forecasting.'),
  make('xid', 'Xid error', 'Training processes disappear on one host.', 'A repeatable GPU hardware/PCIe fault produces Xid events.', ['Failures follow one GPU UUID across jobs.', 'Pod exits non-zero without application error.', 'dmesg records repeated NVRM Xid for that UUID.', 'DCGM diagnostics reproduce the fault after drain.'], 'Drain/quarantine the GPU node and follow hardware remediation guidance.', 'Alert on actionable Xid classes and retain UUID-to-node history.'),
  make('nccl', 'NCCL timeout', 'Multi-node training hangs during collective initialization.', 'One rail is unreachable because its interface has the wrong subnet configuration.', ['Single-node jobs pass; multi-node jobs on rail 2 fail.', 'NCCL log times out connecting one peer address.', 'ip route and ibdev2netdev show rail-2 subnet mismatch.', 'Corrected test interface passes nccl-tests across nodes.'], 'Repair rail configuration and restart from a safe checkpoint.', 'Validate every rail preflight and monitor fabric reachability.'),
  make('roce', 'RoCE misconfiguration', 'RDMA traffic has loss and unstable throughput.', 'Priority flow control is inconsistent across a switch hop.', ['Only the RoCE VLAN degrades under load.', 'Application retransmission/retry counters rise.', 'Switch/NIC counters show pause mismatch and ECN imbalance.', 'A controlled fabric config correction stabilizes perftest.'], 'Align the end-to-end lossless/ECN configuration with network ownership.', 'Automate fabric conformance tests and configuration drift checks.'),
  make('rdma-perf', 'RDMA performance issue', 'RDMA connects but bandwidth is far below baseline.', 'Traffic crosses the wrong NUMA socket between GPU and NIC.', ['One node pair is slow; link state is healthy.', 'ib_write_bw is lower only with the workload binding.', 'nvidia-smi topo -m and numactl show remote NIC/GPU affinity.', 'Binding CPU/GPU/NIC locally restores the baseline.'], 'Correct topology-aware placement and process binding.', 'Publish topology labels and test affinity after hardware changes.'),
  make('storage', 'Storage bottleneck', 'GPU utilization periodically collapses during training.', 'Dataset reads saturate shared storage metadata and throughput.', ['All workers stall at epoch boundaries.', 'GPU duty cycle drops while CPUs wait.', 'iostat and storage telemetry show latency/queue spikes; network is healthy.', 'Cached/sharded data sustains GPU utilization in a controlled run.'], 'Stage or shard data and reduce synchronized metadata pressure.', 'Benchmark the complete data pipeline and size storage to feed GPUs.'),
  make('scaling', 'Training scaling failure', 'Adding nodes yields little throughput improvement.', 'Collective communication dominates because the fabric is oversubscribed.', ['Single-node throughput is normal; efficiency falls with node count.', 'Step traces show AllReduce duration growing sharply.', 'Fabric links are healthy but uplinks saturate at the job boundary.', 'A topology-contained allocation improves scaling efficiency.'], 'Place the job within a suitable fabric domain or reduce communication.', 'Model collective bandwidth and reserve non-oversubscribed capacity.'),
  make('ttft', 'Inference TTFT regression', 'Time to first token doubles while tokens/sec remains stable.', 'Prefill requests queue behind long prompts after batching policy changed.', ['TTFT regresses for long prompts; decode TPOT is unchanged.', 'Server queue time and prefill batch size increased after rollout.', 'GPU is busy; KV capacity is healthy; no network regression.', 'Separating/capping prefill batches restores TTFT in canary.'], 'Roll back or tune prefill scheduling with SLO guardrails.', 'Track queue, prefill, decode, prompt length, TTFT, and TPOT separately.'),
  make('low-gpu', 'Low GPU utilization', 'A training job reports 35% GPU utilization.', 'CPU data preprocessing cannot feed the GPU fast enough.', ['All GPUs dip together between steps.', 'Profiler shows gaps before host-to-device copies.', 'CPU workers saturate; storage and collective links are below capacity.', 'More/tuned loader workers and pinned memory reduce gaps.'], 'Tune or move preprocessing after validating the bottleneck.', 'Include input-pipeline profiling in performance qualification.'),
  make('topology', 'Topology / NUMA issue', 'One of eight GPUs is consistently slower.', 'The Pod CPU set and NIC are remote to that GPU’s NUMA domain.', ['The slowdown follows rank placement, not model data.', 'Per-rank step time isolates rank 7.', 'Topology and cpuset evidence shows remote memory/NIC path.', 'Topology-aligned placement normalizes the rank.'], 'Rebind or reschedule using topology-aware resources.', 'Expose NUMA/PCIe topology and validate rank mapping.'),
  make('high-load', 'Linux high load, idle CPU', 'A model gateway has load average 40 on 16 CPUs while CPU utilization stays below 25%.', 'Many worker threads are stuck in uninterruptible I/O against a degraded network filesystem.', ['Only hosts mounting one dataset path are affected after storage maintenance.', 'Application latency rises, but Kubernetes CPU metrics and HPA remain calm.', 'vmstat b and PSI I/O rise; processes are D-state in an NFS wait function.', 'A controlled request against local storage avoids the stall while the NFS path reproduces it.'], 'Shift traffic or data access away from the degraded path and coordinate storage recovery.', 'Alert on PSI and D-state/latency signals; capacity-test and isolate critical dependency paths.'),
  make('memory-reclaim', 'Linux memory reclaim storm', 'A node is responsive but latency spikes every few minutes and no process has been OOM-killed.', 'A page-cache/anonymous-memory working set exceeds safe capacity, causing direct reclaim and major faults.', ['Nodes with the newest data-loader configuration regress.', 'Pods remain Running; p99 latency spikes without restarts.', 'PSI memory, pgmajfault and direct reclaim rise; swap or cgroup memory pressure is sustained.', 'Reducing loader cache/concurrency on one canary removes reclaim stalls.'], 'Reduce the proven working set or move load; change limits only with capacity evidence.', 'Track PSI, faults, reclaim and working-set composition; load-test memory behavior, not just steady RSS.'),
  make('fd-exhaustion', 'File descriptor exhaustion', 'A Python control service begins returning “too many open files” after several hours.', 'HTTP response bodies/sessions are not closed, leaking sockets until RLIMIT_NOFILE is reached.', ['Only long-running replicas fail; restart temporarily clears symptoms.', 'Readiness fails and client errors show EMFILE.', '/proc/<pid>/fd count grows monotonically; most descriptors are sockets to one API.', 'A canary using context-managed sessions keeps descriptor count stable.'], 'Fail over or restart only after preserving evidence, then deploy the resource-lifecycle fix.', 'Use context managers/pools, bound concurrency, alert on FD utilization, and test repeated execution.'),
  make('retry-storm', 'Python automation retry storm', 'A cluster inventory job turns an API slowdown into a control-plane outage.', 'Every client retries 429/503 responses immediately without jitter, deadline, or concurrency limits.', ['API saturation starts seconds after the inventory schedule fires.', 'Requests multiply while successful inventory completions fall.', 'Structured logs show synchronized attempts; inflight requests and 429s climb together.', 'A canary with retry budget, jitter and concurrency cap completes without amplification.'], 'Pause the job or sharply reduce concurrency, then resume with bounded retry policy.', 'Centralize API client policy; test 429/503 behavior and monitor amplification/deadline exhaustion.'),
  make('partial-automation', 'Partial infrastructure automation failure', 'A Python remediation updates half the nodes, fails, and is then rerun.', 'The workflow is not idempotent and has no durable per-target operation state.', ['Only targets after a specific API timeout are inconsistent.', 'The rerun reports conflicts on already-mutated nodes.', 'Logs lack correlation/target state; dry-run differs from both intended and actual state.', 'A redesigned canary records planned/applied/verified states and safely resumes.'], 'Stop repeated execution, inventory actual state, and reconcile each target through an approved plan.', 'Use idempotent operations, checkpoints, structured results, dry-run, verification, and partial-failure tests.'),
  make('api-etcd', 'Kubernetes API and etcd latency', 'kubectl, controllers, and scheduling slow down across the cluster.', 'A high-cardinality controller list/watch pattern plus slow etcd storage drives API request latency.', ['All namespaces are affected after a new controller rollout.', 'Controller work queues grow; API requests time out across resource types.', 'apiserver inflight/latency and etcd fsync/backend latency rise; quorum remains healthy.', 'Scaling back the controller and stopping its broad relists reduces request and storage pressure.'], 'Roll back or rate-limit the offending client and protect control-plane capacity.', 'Use efficient watches/indexes, API priority/fairness, client budgets, etcd SLOs, and rollout load tests.'),
  make('gitops-drift', 'GitOps reconciliation drift', 'A production setting keeps reverting minutes after operators repair it.', 'Two reconcilers own the same field: GitOps desired state conflicts with an operator/defaulting controller.', ['Only one resource kind drifts after enabling a new operator.', 'Managed fields show alternating managers and repeated updates.', 'Git revision is stable; audit events show two controllers writing the same field.', 'Assigning single ownership in a canary stops the reconciliation loop.'], 'Pause the narrower conflicting reconciliation and restore one authoritative desired state.', 'Define field ownership, admission policy, change paths, and drift alerts; test operator/GitOps interaction.'),
  make('tls-expiry', 'TLS certificate expiry', 'Pods resolve a dependency and establish TCP, but TLS handshakes suddenly fail.', 'The dependency certificate expired because rotation updated storage but not the serving process.', ['All callers fail at the same time; DNS and TCP remain healthy.', 'Clients report certificate expired/not yet valid rather than timeout.', 'openssl s_client shows the expired served certificate; the secret contains a newer certificate.', 'Reloading a canary endpoint serves the new chain and succeeds with hostname verification.'], 'Reload/restart the serving process through its safe procedure or fail over to a valid endpoint.', 'Monitor served-certificate expiry, test rotation/reload, preserve chain/SAN validation, and alert before the renewal window.'),
  make('missing-gpu-metrics', 'Missing DCGM GPU metrics', 'Dashboards show zero GPU utilization for a busy node pool.', 'dcgm-exporter cannot reach the host engine after a NetworkPolicy change; zero is actually missing telemetry.', ['Only one namespace/node pool loses data after policy rollout.', 'Workloads and nvidia-smi show activity while Prometheus panels appear empty/zero.', 'Prometheus target is down and exporter logs show connection failure; DCGM itself is healthy.', 'A least-privilege connectivity rule restores a canary target and real samples.'], 'Restore exporter-to-DCGM connectivity and mark gaps as unknown in dashboards.', 'Alert on target absence/staleness, test telemetry policies, and distinguish zero from missing data.'),
  make('cardinality', 'Prometheus cardinality explosion', 'Prometheus query latency and memory usage spike after a deployment.', 'A request ID was added as a metric label, creating an effectively unbounded time-series dimension.', ['Monitoring degrades immediately after one instrumentation release.', 'Ingestion and head-series count surge; application traffic is normal.', 'Label-value analysis identifies request_id on a high-rate metric.', 'Dropping the label in a canary/collector reduces new-series creation and query latency.'], 'Roll back/drop the unbounded label and protect Prometheus query/ingestion capacity.', 'Enforce label budgets and instrumentation review; use logs/traces for high-cardinality identifiers.'),
  make('slurm-pending', 'Slurm GPU job remains Pending', 'An eight-GPU training job waits although the cluster has idle GPUs.', 'The job requests an unavailable GPU type plus an exclusive-node constraint in the selected partition.', ['Only jobs with the new constraint set remain Pending.', 'squeue reason reports ReqNodeNotAvail/Resources rather than generic capacity.', 'scontrol shows the GPU type/constraint combination matches no eligible node in that partition.', 'A corrected test request becomes eligible without changing cluster state.'], 'Correct the request or use the approved partition/capacity product.', 'Publish valid GRES/constraint combinations, validate submissions, and forecast topology-aware queue demand.'),
  make('bmc-unreachable-fw-update', 'BMC unreachable mid-firmware-update', 'A node\'s BMC stops responding to Redfish and IPMI midway through a scheduled firmware push, with no console access.', 'The BMC firmware update itself bricked the management controller\'s network stack before completing, leaving no out-of-band path at all.', ['Only the one node mid-update is affected; sibling nodes updated earlier in the batch are fine.', 'curl/redfishtool to the BMC times out; ipmitool lanplus also gets no response.', 'The Redfish TaskService resource last reported 62% complete before the listener stopped answering.', 'sol activate also fails, confirming the BMC service processor itself is unresponsive, not just the HTTPS listener.'], 'Escalate to vendor out-of-band recovery (BMC recovery jumper/USB-recovery image or RMA) rather than power-cycling blindly, since a forced power event mid-flash risks corrupting the recovery partition too.', 'Stage firmware updates one node at a time with a verified BMC recovery path documented per vendor before starting a batch, and never update BMC firmware unattended overnight.'),
  make('pxe-boot-after-rma', 'Node fails to PXE-boot after mainboard RMA', 'A returned-from-RMA GPU node with a new mainboard sits at "PXE-E51: No DHCP or proxyDHCP offers were received" and never enters the provisioning system\'s installing state.', 'The mainboard swap changed the node\'s MAC address, and the provisioning system\'s DHCP scope still has only the old MAC pre-registered, so no PXE-specific offer is returned.', ['Only the just-RMA\'d node fails; every other node in the same rack/VLAN PXE-boots normally.', 'tcpdump on the boot VLAN shows a DHCPDISCOVER from the new MAC with no DHCPOFFER in response.', 'The DHCP server\'s lease log and the provisioning system\'s MAC allowlist both show only the pre-RMA MAC address.', 'Registering the new MAC in the provisioning system produces an immediate DHCPOFFER and TFTP fetch on retry.'], 'Register the new MAC address in the provisioning system and DHCP scope, then retry the PXE boot.', 'Make MAC re-registration a mandatory step in the RMA/mainboard-swap runbook, verified via a boot-VLAN tcpdump check before the node is returned to service.'),
  make('bcm-category-drift', 'BCM node category push leaves one node with stale config', 'A category-wide configuration push to the gpu-a100 category completes on 29 of 30 nodes, but gpu-node-09 keeps its old kernel-module parameters because it was hand-edited outside the category months earlier.', 'A prior manual fix applied directly to the node (not through the category) created a persistent per-node override that the category push does not detect or reconcile.', ['Only gpu-node-09 diverges; all other members of gpu-a100 show the new parameters cleanly.', 'cmsh device list -c gpu-a100 shows gpu-node-09 as UP/HEALTHY, masking the config divergence entirely.', 'Diffing the category-rendered config against the node\'s actual /etc/modprobe.d file shows an extra hand-added parameter line absent from the category definition.', 'Reconciling the node-level override back into the category definition (or removing it) and reprovisioning brings the node in line with its 29 siblings.'], 'Reconcile the specific hand-edited file against the category\'s rendered config, then reprovision the node so category membership is authoritative again.', 'Treat any manual edit on a category-managed node as technical debt with a tracked follow-up to fold it into the category definition, and audit for node-level overrides on a recurring schedule.'),
  make('ansible-false-idempotent', 'Ansible playbook reports "changed" on every run', 'A templated DCGM exporter config playbook reports changed=1 on every node on every run, even against nodes nobody has touched since the last run.', 'The Jinja2 template renders a dict-derived YAML block whose key order is not guaranteed stable across runs, so the content-hash idempotency check sees a byte-level diff every time despite semantically identical output.', ['Every node shows changed=1 on every run, including nodes untouched for weeks.', '--check --diff shows the same metrics: block re-emitted with keys in a different order each render, same keys and values.', 'The underlying set_fact merges two group_vars dicts whose merge order depends on filesystem directory-listing order, which is not guaranteed sorted.', 'Sorting the dict with dict2items | sort(attribute=\'key\') before templating produces zero diff on three consecutive runs against an untouched node.'], 'Convert the source data to an explicitly sorted, ordered structure before templating so rendered output is byte-stable when nothing semantically changed.', 'Verify idempotency claims with three consecutive --check --diff runs showing zero diff, not merely a successful exit code, before trusting a playbook\'s changed= count.'),
  make('terraform-state-drift-destroy', 'terraform apply destroys a production resource due to state drift', 'An unrelated tag-only Terraform PR triggers an apply that unexpectedly destroys and recreates a production EBS volume holding checkpoint data.', 'A prior manual console resize of the volume during an incident was never reconciled back into the .tf source, and the resulting size/IOPS-ratio mismatch forces the provider to replace rather than update the resource.', ['The plan for an unrelated tag change shows -/+ on the volume resource, not the expected ~ in-place update.', 'terraform state show reveals state still records the pre-incident 300GiB size while the volume is actually 500GiB in reality.', 'git log on the .tf file shows no commit since well before the manual console resize two weeks earlier.', 'A corrected .tf declaration matching the real 500GiB size produces a clean ~ update with no replacement on a subsequent plan.'], 'Do not apply a plan showing an unexpected -/+ on a resource nobody intended to touch; update the .tf source to match reality first, then re-plan.', 'Require that any manual change to a Terraform-managed resource be followed immediately by a matching .tf update or an explicit terraform state operation, before the next unrelated apply can reach it.'),
  make('slurm-fairshare-starve', 'Slurm fairshare misconfiguration starves a research group\'s priority', 'Physics, climate, and astro jobs queue 10+ hours longer every day for three weeks, with no job outright failing and no single day looking anomalous.', 'A newly onboarded genomics account was given Fairshare=100 copy-pasted from an unrelated infrastructure-testing account, versus Fairshare=20 for the three established accounts, so the multifactor priority plugin favors genomics far out of proportion to its intended allocation.', ['squeue reason code for the affected accounts is (Priority), which reads as normal contention, not a policy bug.', 'sshare -l shows genomics FairShare near 1.0 versus roughly 0.2 for physics/climate/astro.', 'sacctmgr show assoc confirms RawShares of 100 for genomics against 20 for each of the other three accounts.', 'sacctmgr modify account genomics set fairshare=20 followed by a multi-day sshare check shows the ratios normalize as decayed usage history catches up.'], 'Correct the fairshare value to match the agreed proportional allocation, then confirm via sshare -l over several days as usage history decays toward the new weight.', 'Review any new association\'s fairshare value against the existing account tree before activation, and check sshare -l on a recurring cadence rather than only when a PI escalates.'),
  make('slurm-failover-lost-jobs', 'Slurm controller failover appears to lose running jobs', 'After the primary slurmctld fails and the backup takes over, squeue on the backup shows a nearly empty queue even though dozens of jobs were running moments earlier.', 'StateSaveLocation was configured to a path that resolves to local disk on the primary controller rather than genuinely shared storage reachable by both controllers, so the backup had no state to read on takeover.', ['Only failover events show job loss; day-to-day operation on the primary looked completely normal.', 'scontrol show config confirms StateSaveLocation is set, but the path is mounted as local disk on slurmctl-01 only.', 'journalctl -u slurmctld on the backup shows it started clean with an empty state directory rather than reading prior queue state.', 'sacct against slurmdbd still shows the accounting history intact, confirming the loss is queue-state-only, not a database failure.'], 'Fail back to the primary if it is recoverable to avoid further job loss, then remount StateSaveLocation on genuinely shared storage reachable by both controllers before the next failover test.', 'Test controller failover deliberately in a maintenance window, verifying the backup actually reads live queue state from StateSaveLocation, rather than assuming the config file entry alone guarantees shared-storage semantics.'),
  make('mpi-nccl-startup-hang', 'Multi-node MPI+NCCL training job hangs at startup', 'An 8-rank job across two nodes shows zero training progress; all ranks appear alive but nothing advances past process launch.', 'One node\'s MPI/PMIx rank bootstrap never completed because a firewalled out-of-band port prevented that node\'s ranks from being reachable, so the job never even reached the NCCL initialization the team assumed was hanging.', ['srun --overlap ps aux confirms all 8 rank processes exist and are running, ruling out a launch failure.', 'mpirun --report-bindings shows binding output for ranks 0-3 on node A but nothing at all for ranks 4-7 on node B.', 'PMIX_MCA_ptl_base_verbose=5 on node B shows repeated connection-refused attempts to node A\'s PMIx server port.', 'Opening the specific PMIx bootstrap port range between the two nodes produces complete bindings output for all 8 ranks and training proceeds to NCCL initialization.'], 'Open the required PMIx bootstrap port range between the affected nodes and relaunch; do not touch NCCL settings until MPI bootstrap is confirmed complete for every rank.', 'Validate PMIx/MPI bootstrap connectivity between all node pairs as part of node bring-up or firewall-change review, rather than defaulting straight to the NCCL/fabric layer on a startup hang.'),
  make('enroot-gpu-not-visible', 'Enroot/Pyxis job can\'t see the GPU the host can see', 'A researcher\'s srun --container-image job reports "no devices found" from nvidia-smi inside the container, while nvidia-smi on the bare host works fine.', 'The NVIDIA Container Toolkit hook that Enroot needs to bind-mount driver libraries and device files into the rootless filesystem is missing from /etc/enroot/hooks.d/ after a recent BCM image update.', ['Kubernetes-launched GPU Pods on the same node work fine, which initially misleads the on-call toward a driver theory.', 'nvidia-smi -L on the bare host lists all GPUs correctly, ruling out a driver/hardware fault.', 'ls -l /etc/enroot/hooks.d/*nvidia* returns no matching file on the affected node, unlike a known-good node in the same category.', 'Reinstalling the Enroot NVIDIA hook package and rerunning the job shows NVIDIA_VISIBLE_DEVICES populated inside the container and nvidia-smi succeeding.'], 'Reinstall or re-enable the Enroot NVIDIA hook package on the affected node and re-verify with a test container before returning it to the partition.', 'Include the Enroot NVIDIA hook file as an explicit item in the golden-image validation gate, since a working Kubernetes CDI GPU path on the same node proves nothing about Enroot\'s independent hook configuration.'),
  make('selinux-gpu-monitoring-block', 'SELinux enforcing mode silently blocks a GPU monitoring agent', 'The DCGM exporter starts, stays running, and shows no application-level error, but its GPU utilization metrics never populate on nodes that recently received a hardening baseline.', 'SELinux\'s targeted policy has no context mapping for a newer GPUDirect-adjacent device node the exporter needs to read, so enforcing mode silently denies the access without the exporter logging a permission error it can surface.', ['Only nodes that received the new hardening baseline this week are affected; older nodes with the same exporter version work fine.', 'The exporter process log shows no errors at all — it looks healthy from the application\'s own perspective.', 'ausearch -m avc -ts recent on the affected node shows repeated AVC denials against the exporter\'s domain for a specific device-node type.', 'audit2why decodes the denial as a missing type mapping for that device class, and a supplemental SELinux policy module resolves it without disabling enforcement.'], 'Install the correct supplemental SELinux policy module mapping the device-node type the exporter needs, rather than setting the node to permissive mode.', 'Include a policy-module validation step in the hardening-baseline canary gate specifically for any newly exposed GPU/monitoring device class, before the baseline ships fleet-wide.'),
  make('canary-firmware-not-representative', 'Coordinated rollout passes canary but breaks 20% of the fleet', 'A driver+CUDA+NCCL bump passes every canary gate cleanly, then hours into the second rollout wave, roughly a fifth of multi-node training jobs start failing with NCCL timeouts.', 'The canary\'s 8 nodes were all on one NIC firmware revision; the new NCCL version\'s updated transport-capability negotiation interacts badly with a different NIC firmware revision present on 20% of the fleet that the canary never included.', ['dcgm-diag, nccl-tests, and the training smoke job all passed cleanly on every canary node before rollout began.', 'Failures cluster precisely on nodes running one specific ConnectX-7 firmware revision, not randomly across the fleet.', 'The canary node inventory shows all 8 nodes on ConnectX-6 NICs at a single firmware revision, none matching the affected revision.', 'A second canary stratified by NIC model and firmware revision reproduces the timeout on a small controlled set before further rollout.'], 'Halt further rollout waves immediately, roll the affected batch back to the known-good combination, and re-stratify the canary by NIC model and firmware revision before resuming.', 'Make canary node selection an explicit, audited step stratified by NIC model, firmware revision, and GPU SKU, not just "grab idle nodes," before any coordinated change is allowed past the canary gate.'),
  make('cicd-emergency-override-bypass', 'CI/CD emergency override bypasses a destructive Terraform gate', 'A policy-check gate correctly blocks a Terraform plan that would destroy and recreate a production Lustre metadata server\'s storage volume, but the change lands anyway and the volume comes back empty.', 'An engineer used a documented but rarely-audited emergency-override flag to bypass the policy-check stage entirely under deadline pressure, applying the destructive plan directly without the missing change-ticket reference the gate was checking for.', ['conftest test tfplan.json shows a FAIL for the destroy action, confirming the gate worked correctly as designed.', 'The pipeline audit log shows the override flag was invoked immediately after the FAIL, with no incident ticket filed at the time.', 'terraform plan -refresh-only after the fact confirms the volume was recreated with a fresh empty ID, distinct from the original.', 'Recovery time from the empty volume exceeds what the original, properly-ticketed change would have taken end to end.'], 'Restore the metadata server from the most recent backup, then require a post-hoc mandatory incident ticket for the override use within one hour, reviewed on a dashboard.', 'Make the emergency-override path audited and rare rather than removing it: every use triggers an automatic follow-up PR that re-runs the full policy check against what was actually applied.'),
  make('kernel-patch-dkms-break', 'Routine kernel patch breaks the GPU driver DKMS build fleet-wide', 'A maintenance window applies routine kernel errata across the gpu-a100 fleet; after reboot, nvidia-smi fails on every node in the batch with a driver/library version mismatch, though nothing about the NVIDIA driver package changed.', 'The patch pipeline updated the kernel package but never triggered or waited for a DKMS rebuild of the nvidia kernel module against the new kernel headers before the nodes rebooted, so nvidia.ko no longer matches the running kernel.', ['Every node in the patched batch fails identically; nodes not yet in this maintenance wave are unaffected.', 'dmesg | grep -i nvidia shows "Failed to initialize NVML: Driver/library version mismatch" on every affected node.', 'dkms status shows the nvidia module still registered only against the previous kernel version, never rebuilt for the new one.', 'dkms autoinstall against the running kernel rebuilds the module successfully, and nvidia-smi returns clean without a further reboot.'], 'Run dkms autoinstall (or a targeted dkms install for the exact running kernel) to rebuild the module immediately, then verify with nvidia-smi before resuming any drained jobs.', 'Treat "kernel package update" and "DKMS rebuild and verify module load" as one atomic, gated maintenance step per node, never rebooting into a new kernel without a passing DKMS build gate for that exact kernel version.'),
  make('os-hardening-breaks-rdma', 'OS hardening baseline degrades RDMA performance via aggressive defaults', 'RDMA bandwidth on a newly-hardened node pool drops to a fraction of baseline immediately after a CIS-style hardening rollout, with no error reported by any application.', 'The hardening baseline tightened kernel sysctl defaults (rp_filter and socket buffer sizing) and applied a default-deny nftables posture without an explicit allow rule for the RoCE traffic class, throttling and partially dropping RDMA traffic instead of blocking it outright.', ['Only the newly-hardened node pool regresses; nodes pending the rollout still hit baseline RDMA bandwidth.', 'ib_write_bw on the hardened nodes returns roughly a third of the pre-hardening baseline bandwidth with no connection failure.', 'sysctl -a diffed against the pre-hardening baseline shows rp_filter and rmem/wmem defaults tightened beyond what RoCE traffic tolerates well.', 'ethtool -S on the NIC shows rising pause/drop counters correlated with the new nftables ruleset, and adding an explicit allow rule for the RoCE VLAN restores baseline bandwidth.'], 'Add an explicit allow rule for the RoCE/RDMA traffic class and relax the specific sysctl values shown to regress bandwidth, rather than exempting the node pool from hardening entirely.', 'Include an RDMA bandwidth check (ib_write_bw against a recorded baseline) in the hardening-baseline canary gate for any GPU/HPC node pool, since a generic CIS benchmark pass says nothing about fabric-specific performance regressions.'),
];
